CREATE TABLE IF NOT EXISTS finance_budgets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, fiscal_year integer NOT NULL, department_id uuid REFERENCES org_departments(id), amount numeric(16,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'NGN', status text NOT NULL DEFAULT 'draft', owner_employee_id uuid REFERENCES workforce_employees(id), notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS finance_expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), budget_id uuid REFERENCES finance_budgets(id), category text NOT NULL, description text NOT NULL, amount numeric(16,2) NOT NULL, currency text NOT NULL DEFAULT 'NGN', expense_date date NOT NULL, requested_by uuid REFERENCES workforce_employees(id), approved_by uuid REFERENCES workforce_employees(id), status text NOT NULL DEFAULT 'pending', receipt_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS company_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_tag text UNIQUE NOT NULL, asset_type text NOT NULL, name text NOT NULL, description text, acquisition_date date, cost numeric(16,2), currency text DEFAULT 'NGN', status text NOT NULL DEFAULT 'available', assigned_employee_id uuid REFERENCES workforce_employees(id), location text, serial_number text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_type text NOT NULL, reference_id uuid, requested_by uuid REFERENCES workforce_employees(id), approver_role text NOT NULL, decision text NOT NULL DEFAULT 'pending', decided_by uuid REFERENCES workforce_employees(id), decision_note text, created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz);
CREATE INDEX IF NOT EXISTS idx_finance_expenses_status ON finance_expenses(status,expense_date);
CREATE INDEX IF NOT EXISTS idx_company_assets_status ON company_assets(status,assigned_employee_id);